package com.superessence.cuttinx.core.tutorial

import kotlin.math.max
import kotlin.math.min

/**
 * Video tutorials generated by CUTTINX itself: every film is a script (cursor moves, taps, captions,
 * UI changes) played on a simulated app screen by [FilmRenderer]. Nothing is recorded: the films are
 * drawn live, in every language-independent detail, at any resolution, on Android and on PC.
 */
enum class TutoSpace(val label: String) { EDITOR("Éditeur"), TWITCH("Twitch Editor"), BRAND("ID Influenceur") }

enum class Screen { EDITOR, TWITCH, OBS, BRAND }

/** A clip of the simulated timeline. Times in seconds. */
class MClip(
    val id: String, var track: Int, var start: Float, var len: Float, var color: Long, var label: String,
    /** Picture shown in the preview: 0 sunset, 1 city at night, 2 green-screen person, 3 title. */
    var look: Int = 0,
    var transition: String? = null,
    val keyframes: MutableList<Float> = mutableListOf(),
    var badge: String? = null,
) {
    val end get() = start + len
}

class MSlider(val label: String, var value: Float, var display: String)

/** Everything the simulated screen shows at one instant (rebuilt for every frame). */
class Ui {
    var screen = Screen.EDITOR
    val clips = mutableListOf<MClip>()
    var selected: String? = null
    var playhead = 0f
    // left library
    var leftTab = 0
    var leftItems: List<String> = emptyList()
    var leftHi = -1
    // right inspector
    var panel = "Projet"
    val sliders = mutableListOf<MSlider>()
    val toggles = linkedMapOf<String, Boolean>()
    var pressed: String? = null
    // preview
    var zoom = 1f; var panX = 0f; var panY = 0f; var rot = 0f
    var tint: String? = null
    var text: String? = null; var textScale = 1f; var textAlpha = 1f
    var keyed = false
    var mask = 0f          // 0 = none, 1 = circle
    var feather = 0f
    var transition = -1f   // heart reveal progress (−1 = none)
    var look = 0
    var playing = false
    // overlays
    var dialog: String? = null
    var dialogChoice = -1
    var progress = -1f
    var toast: String? = null
    var noise = 1f
    // Twitch / OBS / brand
    var themeIdx = 0
    var channel = "MaChaîne"
    var scene = 0
    var obsSources = mutableListOf("Capture de jeu", "Caméra")
    var obsMenu = false
    var obsProps: String? = null
    var brandName = ""
    var brandNiche = -1
    var brandShown = 0f
    var colorEdit = -1
}

data class Waypoint(val t: Double, val x: Float, val y: Float)
data class Caption(val t0: Double, val t1: Double, val text: String)
private class Ev(val t0: Double, val t1: Double, val f: (Ui, Float) -> Unit)

/** Builder of a film. Coordinates are in the 1280×720 reference of [L]. */
class FilmScript {
    private val events = ArrayList<Ev>()
    val way = ArrayList<Waypoint>()
    val taps = ArrayList<Double>()
    val caps = ArrayList<Caption>()
    private var setup: Ui.() -> Unit = {}

    fun setup(f: Ui.() -> Unit) { setup = f }
    /** Instant change at [t]. */
    fun at(t: Double, f: Ui.() -> Unit) { events += Ev(t, t, { u, _ -> u.f() }) }
    /** Continuous change between [t0] and [t1] (p goes 0 → 1, eased). */
    fun anim(t0: Double, t1: Double, f: Ui.(Float) -> Unit) { events += Ev(t0, t1, { u, p -> u.f(p) }) }
    fun move(t: Double, x: Float, y: Float) { way += Waypoint(t, x, y) }
    /** Moves the finger to (x, y), arriving at [t], and taps there. */
    fun tap(t: Double, x: Float, y: Float) { move(t, x, y); taps += t }
    fun say(t0: Double, t1: Double, text: String) { caps += Caption(t0, t1, text) }
    /** Drags from the current finger position to (x, y) between [t0] and [t1]. */
    fun drag(t0: Double, t1: Double, x: Float, y: Float) { taps += t0; move(t1, x, y) }
    /** Types [text] into [into] between [t0] and [t1]. */
    fun type(t0: Double, t1: Double, text: String, into: Ui.(String) -> Unit) = anim(t0, t1) { p -> into(text.take((text.length * p).toInt().coerceAtMost(text.length))) }

    fun state(t: Double): Ui {
        val u = Ui()
        u.setup()
        for (e in events.sortedBy { it.t0 }) {
            if (t < e.t0) continue
            val p = if (e.t1 <= e.t0) 1f else ((t - e.t0) / (e.t1 - e.t0)).toFloat().coerceIn(0f, 1f)
            e.f(u, ease(p))
        }
        return u
    }

    fun cursor(t: Double): Waypoint? {
        if (way.isEmpty()) return null
        val ws = way.sortedBy { it.t }
        if (t <= ws.first().t) return ws.first()
        for (i in 1 until ws.size) {
            val a = ws[i - 1]; val b = ws[i]
            if (t <= b.t) {
                val p = ease(((t - a.t) / max(1e-6, b.t - a.t)).toFloat().coerceIn(0f, 1f))
                return Waypoint(t, a.x + (b.x - a.x) * p, a.y + (b.y - a.y) * p)
            }
        }
        return ws.last()
    }

    companion object { fun ease(p: Float) = p * p * (3 - 2 * p) }
}

class Film(val id: String, val title: String, val space: TutoSpace, val summary: String, val duration: Double, private val build: FilmScript.() -> Unit) {
    val script: FilmScript by lazy { FilmScript().apply(build) }
    fun state(t: Double) = script.state(t)
    fun caption(t: Double) = script.caps.lastOrNull { t >= it.t0 && t < it.t1 }
    fun stepOf(t: Double): Pair<Int, Int> = script.caps.indexOfLast { t >= it.t0 }.coerceAtLeast(0) + 1 to script.caps.size
}

/** Layout of the simulated screens (1280×720 reference). */
object L {
    const val W = 1280f; const val H = 720f
    // editor
    const val PX = 340f; const val PY = 66f; const val PW = 600f; const val PH = 338f
    const val TL_X = 120f; const val PPS = 90f
    val rowY = floatArrayOf(486f, 540f, 576f, 610f)
    val rowH = floatArrayOf(50f, 32f, 30f, 46f)
    const val RULER_Y = 462f
    const val TOOL_Y = 434f
    const val CAP_Y = 664f
    fun x(sec: Float) = TL_X + sec * PPS
    fun clipCenter(c: MClip) = x(c.start + c.len / 2) to rowY[c.track] + rowH[c.track] / 2
    // top bar buttons
    const val KF_X = 1000f; const val UNDO_X = 1050f; const val REDO_X = 1095f; const val TOP_Y = 28f
    const val EXPORT_X = 1192f
    // tool bar buttons (centre x)
    val tools = listOf("Couper", "Supprimer", "Dupliquer", "Lecture")
    val toolIcons = listOf("Split", "Delete", "Duplicate", "Play")
    fun toolX(i: Int) = 360f + i * 150f
    // left library: tabs column + items
    val tabs = listOf("Media", "Text", "Effects", "Transitions", "Animation", "Music", "Sfx", "Voice", "Pro")
    val tabNames = listOf("Médias", "Textes", "Effets", "Transitions", "Animations", "Musique", "Bruitages", "Voix", "Outils pro")
    fun tabY(i: Int) = 84f + i * 35f
    fun itemY(i: Int) = 104f + i * 40f
    const val ITEM_X = 190f
    // inspector rows
    fun sliderY(i: Int) = 120f + i * 52f
    fun toggleY(i: Int, sliders: Int) = 120f + sliders * 52f + i * 40f
    const val INS_X = 975f; const val INS_W = 280f
}

