            tap(12.6, L.INS_X + 0.66f * L.INS_W, L.sliderY(0) + 26); drag(12.7, 13.8, L.INS_X + 0.25f * L.INS_W, L.sliderY(0) + 26)
            anim(12.7, 13.8) { p -> sliders[0].value = 0.66f - 0.41f * p; sliders[0].display = "${(100 - 60 * p).toInt()} %" }
            tap(14.4, L.INS_X + 0.02f * L.INS_W, L.sliderY(1) + 26); drag(14.5, 15.6, L.INS_X + 0.4f * L.INS_W, L.sliderY(1) + 26)
            anim(14.5, 15.6) { p -> sliders[1].value = 0.4f * p; sliders[1].display = "%.1f s".format(2.4f * p) }
            say(16.0, 19.0, "Astuce : le whoosh juste AVANT la coupe rend la transition bien plus pro.")
        },
        Film("voice", "Réduire le bruit de fond et effets de voix", TutoSpace.EDITOR, "Une voix propre (ventilo, rue, souffle) ou une voix d'hélium en un clic.", 17.0) {
