            move(0.0, 640f, 300f)
            say(0.8, 4.5, "Sélectionne le clip avec ta voix : on voit le bruit entre les phrases.")
            tap(2.4, L.x(5f), L.rowY[3] + 22); at(2.4) { selected = "v"; panel = "Ma voix.m4a" }
            say(4.5, 9.5, "Onglet Voix > « Réduire le bruit de fond ».")
            tap(5.4, 41f, L.tabY(7)); at(5.4) { lib(this, 7, listOf("Réduire le bruit de fond", "Voix studio", "Hélium", "Robot", "Monstre", "Radio", "Fantôme")) }
            tap(7.2, L.ITEM_X, L.itemY(0)); at(7.2) { leftHi = 0; clips.first { it.id == "v" }.badge = "Voice" }
            anim(7.3, 8.8) { p -> noise = 1f - 0.9f * p }
            say(9.5, 14.0, "Pour s'amuser : « Hélium », « Robot », « Monstre »… en direct, sans abîmer l'original.")
            tap(11.0, L.ITEM_X, L.itemY(2)); at(11.0) { leftHi = 2; toast = "Effet « Hélium » ajouté" }
            say(14.0, 17.0, "« Voix studio » : compresseur + de-esser, comme un vrai micro de podcast.")
        },
        Film("export", "Exporter en 1080p / 4K pour TikTok", TutoSpace.EDITOR, "La bonne qualité pour chaque réseau, sans perte.", 15.0) {
            setup { editor(this) }
            move(0.0, 640f, 300f)
            say(0.8, 4.5, "Quand ton montage est prêt : « Exporter » en haut à droite.")
            tap(2.6, L.EXPORT_X, L.TOP_Y); at(2.6) { pressed = "export"; dialog = "export"; dialogChoice = 1 }
            at(3.0) { pressed = null }
            say(4.5, 8.5, "1080p suffit pour TikTok, Reels et Shorts. 4K pour YouTube.")
            tap(6.2, 640f + 110f, 300f); at(6.2) { dialogChoice = 3 }
            say(8.5, 13.5, "Lance l'export : effets, textes et sons sont rendus image par image.")
            tap(9.2, 640f, 420f); at(9.2) { progress = 0f }
            anim(9.3, 12.6) { p -> progress = p }
            at(12.7) { dialog = null; progress = -1f; toast = "Vidéo exportée" }
            say(13.5, 15.0, "Elle est dans ta galerie (téléphone) ou le dossier choisi (PC).")
        },
        Film("obs-pack", "Créer ton pack d'overlays Twitch", TutoSpace.TWITCH, "Thème, couleurs, textes : tout ton habillage de live en 2 minutes.", 20.0) {
            setup { screen = Screen.TWITCH; themeIdx = 0; channel = "MaChaîne" }
            move(0.0, 640f, 400f)
            say(0.8, 5.0, "Choisis un thème : super-héros, anime, mignon, rétro, saisons…")
            tap(2.4, 120f, 260f); at(2.4) { themeIdx = 2 }
            tap(4.0, 320f, 380f); at(4.0) { themeIdx = 5 }
            say(5.0, 10.0, "Écris le nom de ta chaîne : il apparaît sur toutes les scènes.")
            tap(6.0, 620f, 576f)
            type(6.4, 8.6, "LunaGaming") { s -> channel = s.ifEmpty { " " } }
            say(10.0, 14.5, "Onglet Couleurs : touche une couleur, tout l'overlay suit.")
            tap(11.0, 849f, 576f); at(11.0) { colorEdit = 2 }
            tap(12.8, 895f, 576f); at(12.8) { colorEdit = 3 }
            say(14.5, 20.0, "« Exporter le pack OBS » : scènes animées, cadres, alertes, transitions, panneaux.")
            tap(15.6, 1150f, 576f); at(15.6) { progress = 0f }
            anim(15.7, 18.6) { p -> progress = p }
            at(18.7) { progress = -1f; toast = "Pack OBS prêt" }
        },
        Film("obs-install", "Installer les scènes et la transition dans OBS", TutoSpace.TWITCH, "Source Navigateur pour les scènes animées, Stinger pour la transition.", 22.0) {
            setup { screen = Screen.OBS; scene = 0 }
            move(0.0, 640f, 400f)
            say(0.8, 5.0, "Dans OBS : Sources > « + » > « Navigateur ».")
            tap(2.4, 560f, 690f); at(2.4) { obsMenu = true }
            tap(4.0, 600f, 512f); at(4.0) { obsMenu = false; obsProps = "browser" }
            say(5.0, 10.0, "Coche « Fichier local » et choisis scene.html du dossier de la scène. 1920 × 1080.")
            tap(7.0, 408f, 298f); at(7.0) { dialogChoice = 1 }
            tap(9.0, 760f, 470f); at(9.0) { obsProps = null; obsSources.add(0, "Le live va commencer"); scene = 1 }
            say(10.0, 15.5, "Transitions de scène > « + » > « Stinger » > le PNG animé.")
            tap(11.6, 990f, 600f); at(11.6) { obsProps = "stinger" }
            say(15.5, 20.0, "Point de transition : 600 ms. Change de scène : la toile d'araignée passe !")
            tap(16.6, 760f, 470f); at(16.6) { obsProps = null }
            tap(17.6, 150f, 592f); anim(17.6, 18.8) { p -> transition = p; if (p >= 1f) { scene = 2; transition = -1f } }
            say(20.0, 22.0, "Le guide complet est dans LISEZ-MOI.txt du pack.")
        },
        Film("brand", "Créer ton identité de créateur", TutoSpace.BRAND, "Palette, polices, slogans, bios : une image reconnaissable partout.", 16.0) {
            setup { screen = Screen.BRAND }
            move(0.0, 640f, 400f)
            say(0.8, 5.0, "Écris ton nom de créateur et choisis ta niche.")
