            type(2.1, 3.8, "Sakura Chan") { s -> brandName = s }
            tap(4.4, 150f, 250f); at(4.4) { brandNiche = 2 }
            say(5.0, 9.0, "« Créer mon identité » : tout est généré en une seconde.")
            tap(6.4, 240f, 520f); anim(6.6, 8.2) { p -> brandShown = p }
            say(9.0, 13.0, "Palette lisible, polices, slogans, bios TikTok / Insta / YouTube / Twitch.")
            say(13.0, 16.0, "« Utiliser pour mes overlays Twitch » : tes couleurs partout en un clic.")
            tap(14.2, 900f, 640f); at(14.2) { toast = "Couleurs appliquées aux overlays" }
        },
    )

    operator fun get(id: String) = all.firstOrNull { it.id == id }
    fun of(space: TutoSpace) = all.filter { it.space == space }

    /** Total length of the films (shown in the guide). */
    val totalSeconds: Int get() = all.sumOf { it.duration }.toInt()

    internal fun clamp01(v: Float) = min(1f, max(0f, v))
}
